if($a==='match_auto'){$s=$pdo_master->prepare("SELECT i.*,f.vencimento FROM financeiro_cc_itens i JOIN financeiro_cc_faturas f ON f.id=i.fatura_id WHERE i.fatura_id=? AND i.empresa_id=? AND i.natureza='D' AND i.cpcontador IS NULL");$s->execute([$faturaId,$empresa]);$n=0;foreach($s->fetchAll(PDO::FETCH_ASSOC) as $i){$c=cccCandidatosSeguros($i,cccCandidatos($pdo_master,$i,$i['vencimento']));if(count($c)===1){cccVincular($pdo_master,$empresa,(int)$i['id'],(int)$c[0]['CPCONTADOR'],$usuario);$n++;}}header('Location: '.cccUrl($faturaId,'auto').'&qtd='.$n);exit;}
if($a==='vincular_lote'){$matches=$_POST['matches']??[];if(!is_array($matches))$matches=[];$n=0;$pdo_master->beginTransaction();foreach($matches as $itemId=>$cp){$itemId=(int)$itemId;$cp=(int)$cp;if($itemId>0&&$cp>0){cccVincular($pdo_master,$empresa,$itemId,$cp,$usuario);$n++;}}$pdo_master->commit();header('Location: '.cccUrl($faturaId,'lote').'&qtd='.$n);exit;}
