if($a==='gerar'){$ids=array_map('intval',$_POST['itens']??[]);if(!$ids)throw new RuntimeException('Selecione os itens sem match.');$s=$pdo_master->prepare("SELECT f.*,c.nome cartao_nome,c.fornecedor_fcontador FROM financeiro_cc_faturas f JOIN financeiro_cc_cartoes c ON c.id=f.cartao_id WHERE f.id=? AND f.empresa_id=?");$s->execute([$faturaId,$empresa]);$f=$s->fetch(PDO::FETCH_ASSOC);$n=0;foreach($ids as $id){$s=$pdo_master->prepare("SELECT * FROM financeiro_cc_itens WHERE id=? AND fatura_id=? AND empresa_id=? AND natureza='D' AND cpcontador IS NULL");$s->execute([$id,$faturaId,$empresa]);if($i=$s->fetch(PDO::FETCH_ASSOC)){$cp=cccGerarCp($pdo_master,$i,$f,$usuario);$pdo_master->prepare("UPDATE financeiro_cc_itens SET cpcontador=?,status='GERADO',usuario_id=?,conciliado_em=NOW() WHERE id=?")->execute([$cp,$usuario?:null,$id]);$n++;}}header('Location: '.cccUrl($faturaId,'gerados').'&qtd='.$n);exit;}
}}catch(Throwable $e){if($pdo_master->inTransaction())$pdo_master->rollBack();$erro=$e->getMessage();}
$ok=$_GET['ok']??'';$msg=['cartao'=>'Cartao salvo.','importada'=>'Fatura importada sem gerar financeiro.','vinculado'=>'CP conciliado.'][$ok]??($ok==='auto'?'Matches automaticos: '.(int)($_GET['qtd']??0):($ok==='gerados'?'CPs gerados: '.(int)($_GET['qtd']??0):''));$fornecedores=buscarFornecedoresCartaoCredito($pdo_master,$empresa);$s=$pdo_master->prepare("SELECT c.*,COALESCE(NULLIF(f.APELIDO,''),f.NOME) fornecedor FROM financeiro_cc_cartoes c JOIN armazem_cp003 f ON f.EMPRESA=c.empresa_id AND f.FCONTADOR=c.fornecedor_fcontador WHERE c.empresa_id=? ORDER BY c.nome");$s->execute([$empresa]);$cartoes=$s->fetchAll(PDO::FETCH_ASSOC);$editar=null;foreach($cartoes as $c)if((int)$c['id']===(int)($_GET['editar']??0))$editar=$c;$ativos=array_filter($cartoes,fn($c)=>$c['ativo']==='S');$s=$pdo_master->prepare("SELECT f.*,c.nome cartao_nome FROM financeiro_cc_faturas f JOIN financeiro_cc_cartoes c ON c.id=f.cartao_id WHERE f.empresa_id=? ORDER BY f.vencimento DESC");$s->execute([$empresa]);$faturas=$s->fetchAll(PDO::FETCH_ASSOC);$fatura=null;$itens=[];if($faturaId){$s=$pdo_master->prepare("SELECT f.*,c.nome cartao_nome,c.fornecedor_fcontador,c.fornecedor_fcontador FROM financeiro_cc_faturas f JOIN financeiro_cc_cartoes c ON c.id=f.cartao_id WHERE f.id=? AND f.empresa_id=?");$s->execute([$faturaId,$empresa]);$fatura=$s->fetch(PDO::FETCH_ASSOC);$s=$pdo_master->prepare("SELECT * FROM financeiro_cc_itens WHERE fatura_id=? ORDER BY data_compra,id");$s->execute([$faturaId]);$itens=$s->fetchAll(PDO::FETCH_ASSOC);}
