sm btn-primary">Conciliar</button></form><?php else:?><span class="badge text-bg-warning">Sem match - gerar CP</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></form><form method="post" id="auto"><input type="hidden" name="acao" value="match_auto"><input type="hidden" name="fatura_id" value="<?=$faturaId?>"></form><?php endif;?>
